<?php
defined( 'ABSPATH' ) || exit;
get_header();
$opt = fn($key,$default='') => function_exists('morgenbrot_get_option') ? morgenbrot_get_option($key,$default) : $default;
$home = fn($key,$default='') => function_exists('morgenbrot_home_value') ? morgenbrot_home_value($key,$default) : $default;
$ids = fn($value) => array_values(array_filter(array_map('absint',explode(',',(string)$value))));
$product_args=array('post_type'=>'bakery_product','posts_per_page'=>max(1,absint($opt('featured_count',4))));
if($ids($opt('featured_ids'))) $product_args['post__in']=$ids($opt('featured_ids'));
else {$product_args['meta_key']='_morgenbrot_featured';$product_args['meta_value']='1';}
$products=get_posts($product_args);
$location_args=array('post_type'=>'bakery_location','posts_per_page'=>-1,'orderby'=>'menu_order title','order'=>'ASC');
if($ids($opt('location_ids'))) $location_args['post__in']=$ids($opt('location_ids'));
$locations=get_posts($location_args);
$sections=array_filter(array_map('sanitize_key',explode(',',$opt('home_sections','hero,products,features,promotion,categories,story,locations,testimonials,faq,final_cta'))));
?>
<main id="main-content">
<?php foreach($sections as$section): switch($section):
case 'hero': ?>
<section class="hero"><div class="shell hero-grid"><div><p class="eyebrow"><?php echo esc_html($opt('hero_eyebrow'));?></p><h1><?php echo wp_kses_post(nl2br(esc_html($opt('hero_title'))));?></h1><p class="lead"><?php echo esc_html($opt('hero_text'));?></p><div class="button-row"><a class="button" href="<?php echo esc_url($opt('hero_primary_url',get_post_type_archive_link('bakery_product')));?>"><?php echo esc_html($opt('hero_primary_text','Unser Sortiment'));?></a><a class="text-link" href="<?php echo esc_url($opt('hero_secondary_url',get_post_type_archive_link('bakery_location')));?>"><?php echo esc_html($opt('hero_secondary_text','Filiale finden'));?> →</a></div></div><div class="hero-art"><?php $image=absint($opt('hero_image_id'));if($image)echo wp_get_attachment_image($image,'large',false,array('alt'=>$opt('hero_title'),'class'=>'fallback-image'));else morgenbrot_placeholder('bread');?><span class="stamp">Seit<br>morgens<br>frisch</span></div></div></section>
<?php break;case 'products': ?>
<section class="section shell"><div class="section-head"><div><p class="eyebrow"><?php echo esc_html($home('products_eyebrow'));?></p><h2><?php echo esc_html($home('products_title'));?></h2></div><a class="text-link" href="<?php echo esc_url(get_post_type_archive_link('bakery_product'));?>"><?php echo esc_html($home('products_link_text'));?></a></div><div class="card-grid products"><?php foreach($products as$post){setup_postdata($post);get_template_part('template-parts/product','card');}wp_reset_postdata();?></div></section>
<?php break;case 'features':$features=json_decode($opt('feature_items','[]'),true)?:array(); ?>
<section class="section features"><div class="shell four-grid"><?php foreach($features as$f):?><article><span><?php echo esc_html($f['icon']??'');?></span><h3><?php echo esc_html($f['title']??'');?></h3><p><?php echo esc_html($f['text']??'');?></p></article><?php endforeach;?></div></section>
<?php break;case 'promotion':if(!$home('offer_enabled','1'))break; ?>
<section class="section shell"><div class="weekly"><div><p class="eyebrow"><?php echo esc_html($home('offer_eyebrow'));?></p><h2><?php echo esc_html($home('offer_title'));?></h2><p><?php echo esc_html($home('offer_text'));?></p><strong><?php echo esc_html($home('offer_price'));?> <small><?php echo esc_html($home('offer_note'));?></small></strong><?php if($home('offer_button_text')&&$home('offer_button_url')):?><p><a class="button" href="<?php echo esc_url($home('offer_button_url'));?>"><?php echo esc_html($home('offer_button_text'));?></a></p><?php endif;?></div><div><?php $image=absint($home('offer_image_id'));if($image)echo wp_get_attachment_image($image,'large',false,array('alt'=>$home('offer_title'),'class'=>'fallback-image'));else morgenbrot_placeholder('basket');?></div></div></section>
<?php break;case 'categories':$term_args=array('taxonomy'=>'bakery_product_category','hide_empty'=>false);if($ids($opt('category_ids'))) $term_args['include']=$ids($opt('category_ids'));$terms=get_terms($term_args); ?>
<section class="section shell"><div class="section-head"><div><p class="eyebrow"><?php echo esc_html($home('categories_eyebrow'));?></p><h2><?php echo esc_html($home('categories_title'));?></h2></div></div><div class="category-grid"><?php if(!is_wp_error($terms))foreach($terms as$term):$cat=sanitize_title($term->name);?><a href="<?php echo esc_url(add_query_arg('kategorie',$term->slug,get_post_type_archive_link('bakery_product')));?>"><span class="category-icon"><svg viewBox="0 0 36 36" aria-hidden="true"><?php if('brot'===$cat):?><path d="M7 25V16c0-6 5-10 11-10s11 4 11 10v9c0 3-2 5-5 5H12c-3 0-5-2-5-5Z"/><path d="m12 11 3 5m3-8 2 6m5-3-2 5"/><?php elseif('brotchen'===$cat):?><path d="M4 24c0-5 4-9 9-9s9 4 9 9c0 4-3 6-9 6s-9-2-9-6Zm14-5c1-4 4-7 8-7 5 0 8 4 8 9 0 4-3 6-9 6h-3"/><path d="m9 18 3 5m4-5-2 5m9-8 2 5m4-4-1 5"/><?php elseif('geback'===$cat):?><path d="M5 25C8 10 20 5 31 10c-2 13-12 21-26 15Z"/><path d="M9 23c5-1 9-4 12-8m-6 9c4-2 7-5 9-9m-3 7c3-2 5-5 6-9"/><?php elseif('getranke'===$cat||'getraenke'===$term->slug):?><path d="M8 14h16v7a7 7 0 0 1-7 7h-2a7 7 0 0 1-7-7v-7Z"/><path d="M24 16h2a4 4 0 0 1 0 8h-2M13 11c-2-2 2-3 0-6m7 6c-2-2 2-3 0-6M6 30h23"/><?php elseif('kuchen'===$cat):?><path d="m7 14 12-6 11 8-11 5-12-7Z"/><path d="M7 14v11l12 5V21m11-5v10l-11 4"/><path d="m12 12 11 6m-4-10v4"/><?php else:?><path d="M6 14h24L27 28H9L6 14Z"/><path d="m8 14 10-7 10 7M10 19h16m-14 4h12"/><?php endif;?></svg></span><?php echo esc_html($term->name);?></a><?php endforeach;?></div><style>.category-icon{display:grid;place-items:center;width:42px;height:42px;color:#c68a3a}.category-icon svg{width:36px;height:36px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}</style></section>
<?php break;case 'story': ?>
<section class="section story" id="ueber-uns"><div class="shell split"><div><?php $image=absint($opt('story_image_id'));if($image)echo wp_get_attachment_image($image,'large',false,array('alt'=>$opt('story_title'),'class'=>'fallback-image'));else morgenbrot_placeholder('wheat');?></div><div><p class="eyebrow"><?php echo esc_html($home('story_eyebrow'));?></p><h2><?php echo esc_html($opt('story_title'));?></h2><p class="lead"><?php echo esc_html($opt('story_text'));?></p><p><?php echo esc_html($home('story_extra'));?></p><a class="text-link" href="<?php echo esc_url($opt('story_button_url'));?>"><?php echo esc_html($opt('story_button_text'));?> →</a></div></div></section>
<?php break;case 'locations': ?>
<section class="section shell" id="filialen"><div class="section-head"><div><p class="eyebrow"><?php echo esc_html($home('locations_eyebrow'));?></p><h2><?php echo esc_html($home('locations_title'));?></h2></div></div><div class="card-grid locations"><?php foreach($locations as$post){setup_postdata($post);get_template_part('template-parts/location','card');}wp_reset_postdata();?></div><?php get_template_part('template-parts/locations','map');?></section>
<?php break;case 'testimonials':$items=json_decode($opt('testimonials','[]'),true)?:array(); ?>
<section class="section testimonials"><div class="shell"><p class="eyebrow"><?php echo esc_html($home('testimonials_eyebrow'));?></p><h2><?php echo esc_html($home('testimonials_title'));?></h2><div class="three-grid"><?php foreach($items as$item):?><blockquote><p><?php echo esc_html($item['quote']??'');?></p><cite><?php echo esc_html($item['name']??'');?></cite></blockquote><?php endforeach;?></div></div></section>
<?php break;case 'faq':$items=json_decode($opt('faq_items','[]'),true)?:array(); ?>
<section class="section shell faq"><p class="eyebrow"><?php echo esc_html($home('faq_eyebrow'));?></p><h2><?php echo esc_html($home('faq_title'));?></h2><?php foreach($items as$item):?><details><summary><?php echo esc_html($item['question']??'');?></summary><p><?php echo esc_html($item['answer']??'');?></p></details><?php endforeach;?></section>
<?php break;case 'final_cta': ?>
<section class="cta"><div class="shell"><div><p class="eyebrow"><?php echo esc_html($home('final_eyebrow'));?></p><h2><?php echo esc_html($opt('final_title'));?></h2><p><?php echo esc_html($opt('final_text'));?></p></div><a class="button light" href="<?php echo esc_url($opt('final_button_url'));?>"><?php echo esc_html($opt('final_button_text'));?></a></div></section>
<?php break;endswitch;endforeach;?>
</main><?php get_footer();
